<?php
declare(strict_types=1);
require __DIR__.'/config.php'; require_login(); require __DIR__.'/patient-layout.php';
$pdo=db();
function inv2_amount(string $v):float{$v=str_replace(' ','',trim($v));return $v===''?0:(float)(str_contains($v,',')?str_replace(',','.',str_replace('.','',$v)):str_replace('.','',$v));}
function inv2_date(string $v):?string{if(!preg_match('/^(\d{2})\.(\d{2})\.(\d{4})$/',trim($v),$p))return null;return checkdate((int)$p[2],(int)$p[1],(int)$p[3])?sprintf('%04d-%02d-%02d',(int)$p[3],(int)$p[2],(int)$p[1]):null;}
function inv2_display_date(string $v):string{return preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$v,$p)?$p[3].'.'.$p[2].'.'.$p[1]:$v;}
$stocks=$pdo->query('SELECT id,stock_code,stock_name,stock_type,vat_rate,sale_price FROM stock_cards ORDER BY stock_name,stock_code')->fetchAll();
$stockIds=array_fill_keys(array_map(static fn($r)=>(int)$r['id'],$stocks),true);
$stockTypes=[];foreach($stocks as $stock)$stockTypes[(int)$stock['id']]=(string)($stock['stock_type']??'');
$lists=$pdo->query('SELECT i.stock_id,i.list_price,l.valid_from,l.valid_until FROM stock_price_list_items i INNER JOIN stock_price_lists l ON l.id=i.price_list_id ORDER BY l.valid_from DESC,l.id DESC')->fetchAll();
$accounts=$pdo->query("SELECT id,code,title,short_name FROM current_accounts WHERE account_type IN ('supplier','both') ORDER BY title")->fetchAll();
$accountIds=array_fill_keys(array_map(static fn($r)=>(int)$r['id'],$accounts),true);
$original=trim((string)($_GET['edit_invoice']??$_POST['original_invoice_no']??''));$editing=$original!=='';
$form=['account_id'=>'','invoice_no'=>'','movement_date'=>date('d.m.Y')];$rows=[];$error='';
if($editing&&$_SERVER['REQUEST_METHOD']!=='POST'){$q=$pdo->prepare('SELECT m.stock_id,m.quantity,COALESCE(m.unit,"Adet") unit,CASE WHEN COALESCE(m.discount_rate,0)>0 AND m.discount_rate<100 THEN ROUND(m.unit_cost/(1-m.discount_rate/100),2) ELSE m.unit_cost END unit_cost,m.purchase_price purchase_total,m.sale_price,m.vat_rate,COALESCE(m.discount_rate,0) discount_rate,m.serial_numbers,m.current_account_id,m.invoice_no,m.movement_date FROM stock_movements m WHERE m.movement_type="Giriş" AND LOWER(TRIM(m.invoice_no))=LOWER(TRIM(?)) ORDER BY m.id');$q->execute([$original]);$rows=$q->fetchAll();if(!$rows){http_response_code(404);exit('Fatura bulunamadı.');}$form=['account_id'=>(string)$rows[0]['current_account_id'],'invoice_no'=>(string)$rows[0]['invoice_no'],'movement_date'=>inv2_display_date((string)$rows[0]['movement_date'])];}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$form=['account_id'=>trim((string)($_POST['account_id']??'')),'invoice_no'=>trim((string)($_POST['invoice_no']??'')),'movement_date'=>trim((string)($_POST['movement_date']??''))];$rows=array_values((array)($_POST['rows']??[]));$accountId=filter_var($form['account_id'],FILTER_VALIDATE_INT);$date=inv2_date($form['movement_date']);
 if(!$accountId||!isset($accountIds[(int)$accountId])||$form['invoice_no']===''||!$date||!$rows)$error='Cari, fatura no, gg.aa.yyyy biçiminde tarih ve en az bir kalem zorunludur.';
 if($error===''){$sql='SELECT 1 FROM stock_movements WHERE movement_type="Giriş" AND LOWER(TRIM(invoice_no))=LOWER(TRIM(?))';$params=[$form['invoice_no']];if($editing){$sql.=' AND LOWER(TRIM(invoice_no))<>LOWER(TRIM(?))';$params[]=$original;}$d=$pdo->prepare($sql.' LIMIT 1');$d->execute($params);if($d->fetchColumn())$error='Bu fatura numarası daha önce kullanılmıştır. Aynı fatura numarasıyla ikinci kayıt yapılamaz.';}
 $valid=[];if($error==='')foreach($rows as $i=>$r){$stockId=filter_var($r['stock_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($r['quantity']??null,FILTER_VALIDATE_INT);$unit=in_array((string)($r['unit']??''),['Adet','Kutu','Kg'],true)?(string)$r['unit']:'';$vat=in_array((string)($r['vat_rate']??''),['0','10','20'],true)?(int)$r['vat_rate']:-1;$cost=inv2_amount((string)($r['unit_cost']??''));$discount=inv2_amount(str_replace('%','',(string)($r['discount_rate']??'0')));$sale=inv2_amount((string)($r['sale_price']??''));$priceSource=(($r['price_source']??'unit')==='total')?'total':'unit';$enteredTotal=inv2_amount((string)($r['purchase_total']??''));if(!$stockId||!isset($stockIds[(int)$stockId])||!$qty||$qty<1||$unit===''||$vat<0||$cost<0||$discount<0||$discount>=100||$sale<0||$enteredTotal<0){$error=($i+1).'. kalemdeki bilgileri kontrol edin.';break;}$serials=json_decode((string)($r['serial_numbers']??'[]'),true);if(!is_array($serials))$serials=[];$serials=array_values(array_unique(array_filter(array_map(static fn($v)=>trim((string)$v),$serials),static fn($v)=>$v!=='')));if(!in_array($stockTypes[(int)$stockId]??'',['İşitme Cihazı','Şarj Cihazı'],true))$serials=[];$serials=array_slice($serials,0,(int)$qty);if($priceSource==='total'){$total=round($enteredTotal,2);$netCost=round($total/$qty,2);}else{$netCost=round($cost*(1-$discount/100),2);$total=round($netCost*$qty,2);}$valid[]=['id'=>(int)$stockId,'qty'=>(int)$qty,'unit'=>$unit,'vat'=>$vat,'cost'=>$cost,'discount'=>$discount,'net_cost'=>$netCost,'sale'=>$sale,'total'=>$total,'serials'=>$serials];}
 if($error==='')try{$pdo->beginTransaction();if($editing){$x=$pdo->prepare('DELETE FROM stock_movements WHERE movement_type="Giriş" AND LOWER(TRIM(invoice_no))=LOWER(TRIM(?))');$x->execute([$original]);}$insert=$pdo->prepare('INSERT INTO stock_movements(stock_id,movement_type,quantity,unit,movement_date,current_account_id,invoice_no,purchase_price,sale_price,vat_rate,unit_cost,discount_rate,serial_numbers) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$card=$pdo->prepare('UPDATE stock_cards SET purchase_price=?,sale_price=?,vat_rate=?,unit_cost=? WHERE id=?');foreach($valid as $r){$insert->execute([$r['id'],'Giriş',$r['qty'],$r['unit'],$date,(int)$accountId,$form['invoice_no'],$r['total'],$r['sale'],$r['vat'],$r['net_cost'],$r['discount'],json_encode($r['serials'],JSON_UNESCAPED_UNICODE)]);$card->execute([$r['net_cost'],$r['sale'],$r['vat'],$r['net_cost'],$r['id']]);}$pdo->commit();header('Location: '.url('invoice-list.php?saved=1'));exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Fatura kaydedilemedi: '.$e->getMessage();}
}
patient_header($editing?'Fatura Düzenle':'Fatura Girişi','stock');?>
<main class="patient-container inv2"><section><header><h1><?=$editing?'Fatura Düzenle':'Fatura Girişi'?></h1><p>Tüm fatura kalemlerini birlikte yönetin.</p></header><?php if($error):?><p class="err"><?=e($error)?></p><?php endif?><form method="post" novalidate><input type="hidden" name="csrf" value="<?=csrf()?>"><?php if($editing):?><input type="hidden" name="original_invoice_no" value="<?=e($original)?>"><?php endif?><div class="head"><label>Cari *<select name="account_id"><option value="">Seçiniz</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$form['account_id']==$a['id']?'selected':''?>><?=e($a['short_name']?:$a['title'])?></option><?php endforeach?></select></label><label>Fatura No *<input name="invoice_no" value="<?=e($form['invoice_no'])?>"></label><label>Giriş Tarihi *<input name="movement_date" maxlength="10" inputmode="numeric" placeholder="gg.aa.yyyy" value="<?=e($form['movement_date'])?>"></label></div><div class="wrap"><table><thead><tr><th>Sıra</th><th>Stok Kartı</th><th>Miktar</th><th>Birim</th><th>Birim Fiyatı (TL)</th><th>KDV</th><th>KDV Tutarı (TL)</th><th>İskonto Oranı</th><th>İskonto Tutarı (TL)</th><th>Alış Toplamı (TL)</th><th>Liste Fiyatı</th><th>Satış Fiyatı (TL)</th><th></th></tr></thead><tbody id="rows"></tbody></table></div><dialog id="serialDialog"><div class="serial-head"><div><h2>Seri Numaraları</h2><p id="serialStock"></p></div><button type="button" class="serial-close" aria-label="Kapat">×</button></div><div id="serialFields" class="serial-fields"></div><div class="serial-actions"><button type="button" class="serial-cancel">Vazgeç</button><button type="button" class="serial-confirm">Tamam</button></div></dialog><footer><button type="button" id="add" class="add" title="Satır Ekle">+</button><a class="cancel" href="<?=e(url('invoice-list.php'))?>">↶</a><button class="save" title="Kaydet"><svg viewBox="0 0 24 24"><path d="M5 3h11l3 3v16H3V5a2 2 0 0 1 2-2zM7 3v6h8V3M7 21v-7h10v7"/></svg></button></footer></form></section></main>
<script>
(()=>{const stocks=<?=json_encode($stocks,JSON_UNESCAPED_UNICODE)?>,lists=<?=json_encode($lists,JSON_UNESCAPED_UNICODE)?>,initial=<?=json_encode($rows,JSON_UNESCAPED_UNICODE)?>,body=document.getElementById('rows'),date=document.querySelector('[name=movement_date]'),serialDialog=document.getElementById('serialDialog'),serialFields=document.getElementById('serialFields'),serialStock=document.getElementById('serialStock'),money=v=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0)),num=v=>Number(String(v||'').replaceAll('.','').replace(',','.'))||0,iso=()=>{const m=date.value.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);return m?m[3]+'-'+m[2]+'-'+m[1]:''},lp=id=>lists.find(x=>String(x.stock_id)===String(id)&&x.valid_from<=iso()&&x.valid_until>=iso());let activeSerialRow=null;
 const summaryBox=document.createElement('div');summaryBox.className='invoice-summary';summaryBox.setAttribute('aria-label','Fatura toplamları');summaryBox.innerHTML='<table><tbody><tr><th>Toplam Tutar</th><td id="summaryGross">0,00 TL</td></tr><tr><th>Toplam İskonto Tutarı</th><td id="summaryDiscount">0,00 TL</td></tr><tr><th>Toplam KDV Tutarı (%10)</th><td id="summaryVat10">0,00 TL</td></tr><tr><th>Toplam KDV Tutarı (%20)</th><td id="summaryVat20">0,00 TL</td></tr><tr><th>Toplam Alış Tutarı</th><td id="summaryPurchase">0,00 TL</td></tr></tbody></table>';document.querySelector('.wrap').after(summaryBox);
 const serialArray=input=>{try{const value=JSON.parse(input.value||'[]');return Array.isArray(value)?value.map(v=>String(v)):[]}catch(_){return[]}},syncSerialButton=r=>{const count=serialArray(r.querySelector('.serials')).filter(v=>v.trim()).length,button=r.querySelector('.serial-button');button.classList.toggle('has-serials',count>0);button.title=count?`${count} seri numarası girildi`:'Seri Numaraları'};
 function openSerial(r){activeSerialRow=r;const qty=Math.max(1,Number(r.querySelector('.qty').value)||1),values=serialArray(r.querySelector('.serials'));serialStock.textContent=r.querySelector('.search').value;serialFields.replaceChildren(...Array.from({length:qty},(_,i)=>{const label=document.createElement('label'),span=document.createElement('span'),input=document.createElement('input');span.textContent=`${i+1}. Seri Numarası`;input.value=values[i]||'';input.autocomplete='off';label.append(span,input);return label}));serialDialog.showModal();serialFields.querySelector('input')?.focus()}
 function updateSummary(){let grossTotal=0,vat10Total=0,vat20Total=0,discountTotal=0,purchaseTotal=0;[...body.rows].forEach(r=>{const qty=Number(r.querySelector('.qty')?.value||0),purchase=num(r.querySelector('.purchase-total')?.value||0),vat=Number(r.querySelector('.vat')?.value||0),cost=num(r.querySelector('.cost')?.value||0),discount=num((r.querySelector('.discount')?.value||'').replace('%',''));grossTotal+=cost*qty;purchaseTotal+=purchase;if(vat===10)vat10Total+=purchase*.10;if(vat===20)vat20Total+=purchase*.20;discountTotal+=cost*qty*discount/100});summaryBox.querySelector('#summaryGross').textContent=money(grossTotal)+' TL';summaryBox.querySelector('#summaryVat10').textContent=money(vat10Total)+' TL';summaryBox.querySelector('#summaryVat20').textContent=money(vat20Total)+' TL';summaryBox.querySelector('#summaryDiscount').textContent=money(discountTotal)+' TL';summaryBox.querySelector('#summaryPurchase').textContent=money(purchaseTotal+vat10Total+vat20Total)+' TL'}
 function names(){[...body.rows].forEach((r,i)=>{r.querySelector('.seq').textContent=i+1;for(const [c,n]of[['.sid','stock_id'],['.qty','quantity'],['.unit','unit'],['.vat','vat_rate'],['.cost','unit_cost'],['.discount','discount_rate'],['.purchase-total','purchase_total'],['.price-source','price_source'],['.sale','sale_price'],['.serials','serial_numbers']])r.querySelector(c).name=`rows[${i}][${n}]`})}
 function add(data={}){const r=document.createElement('tr');r.innerHTML='<td class="seq"></td><td class="picker"><input type="hidden" class="sid"><input class="search" placeholder="Stok kartı ara" autocomplete="off"><div class="results" hidden></div></td><td><input class="qty" type="number" min="1"></td><td><select class="unit"><option>Adet</option><option>Kutu</option><option>Kg</option></select></td><td><input class="cost" inputmode="decimal"></td><td><select class="vat"><option value="0">%0</option><option value="10">%10</option><option value="20">%20</option></select></td><td class="vat-total">0,00 TL</td><td><input class="discount" inputmode="decimal"></td><td class="discount-total">0,00 TL</td><td><input class="purchase-total" inputmode="decimal"><input type="hidden" class="price-source"></td><td class="list">—</td><td><input class="sale" inputmode="decimal"></td><td class="row-actions"><input type="hidden" class="serials"><button type="button" class="serial-button" title="Seri Numaraları" hidden><i class="ti tabler-barcode"></i></button><button type="button" class="remove">×</button></td>';const sid=r.querySelector('.sid'),search=r.querySelector('.search'),results=r.querySelector('.results'),qty=r.querySelector('.qty'),cost=r.querySelector('.cost'),vat=r.querySelector('.vat'),vatTotal=r.querySelector('.vat-total'),discount=r.querySelector('.discount'),discountTotal=r.querySelector('.discount-total'),purchaseTotal=r.querySelector('.purchase-total'),priceSource=r.querySelector('.price-source'),sale=r.querySelector('.sale'),list=r.querySelector('.list'),serials=r.querySelector('.serials'),serialButton=r.querySelector('.serial-button');qty.value=data.quantity||1;r.querySelector('.unit').value=data.unit||'Adet';const vatValue=[0,10,20].includes(Number(data.vat_rate))?Number(data.vat_rate):0;vat.value=String(vatValue);cost.value=money(data.unit_cost);discount.value='%'+money(data.discount_rate);purchaseTotal.value=money(data.purchase_total);priceSource.value=Object.prototype.hasOwnProperty.call(data,'purchase_total')?'total':'unit';sale.value=money(data.sale_price);serials.value=typeof data.serial_numbers==='string'?data.serial_numbers:JSON.stringify(data.serial_numbers||[]);const rate=()=>Math.min(99.99,Math.max(0,num(discount.value.replace('%','')))),factor=()=>1-rate()/100,calcDiscount=()=>{discountTotal.textContent=money(num(cost.value)*Number(qty.value||0)*rate()/100)+' TL'},calcVat=()=>{vatTotal.textContent=money(num(purchaseTotal.value)*Number(vat.value||0)/100)+' TL';calcDiscount()},calcTotal=()=>{purchaseTotal.value=money(num(cost.value)*Number(qty.value||0)*factor());calcVat()},calcUnit=()=>{const count=Number(qty.value||0),f=factor();if(count>0&&f>0)cost.value=money(num(purchaseTotal.value)/(count*f));calcVat()},recalc=()=>priceSource.value==='total'?calcUnit():calcTotal(),refresh=()=>{const x=lp(sid.value);list.textContent=x?money(Number(x.list_price||0)*Number(qty.value||0))+' TL':'—'},pick=s=>{sid.value=s.id;search.value=s.stock_name;if(data.sale_price==null)sale.value=money(s.sale_price);const tracked=['İşitme Cihazı','Şarj Cihazı'].includes(s.stock_type);serialButton.hidden=!tracked;if(!tracked)serials.value='[]';syncSerialButton(r);refresh();results.hidden=true};search.oninput=()=>{sid.value='';serialButton.hidden=true;const q=search.value.trim().toLocaleLowerCase('tr-TR'),found=q.length<2?[]:stocks.filter(s=>(s.stock_code+' '+s.stock_name).toLocaleLowerCase('tr-TR').includes(q)).slice(0,12);results.replaceChildren(...found.map(s=>{const b=document.createElement('button');b.type='button';b.textContent=s.stock_name;b.onclick=()=>pick(s);return b}));results.hidden=!found.length};qty.oninput=()=>{recalc();refresh()};cost.oninput=()=>{priceSource.value='unit';calcTotal()};vat.onchange=calcVat;discount.oninput=recalc;purchaseTotal.oninput=()=>{priceSource.value='total';calcUnit()};cost.onblur=()=>cost.value=money(num(cost.value));discount.onblur=()=>{discount.value='%'+money(rate());recalc()};purchaseTotal.onblur=()=>{purchaseTotal.value=money(num(purchaseTotal.value));calcUnit()};sale.onblur=()=>sale.value=money(num(sale.value));serialButton.onclick=()=>openSerial(r);r.querySelector('.remove').onclick=()=>{if(body.children.length>1){r.remove();names()}};const chosen=stocks.find(s=>String(s.id)===String(data.stock_id||''));if(chosen)pick(chosen);recalc();body.append(r);names()}
body.addEventListener('input',updateSummary);body.addEventListener('change',updateSummary);new MutationObserver(()=>queueMicrotask(updateSummary)).observe(body,{childList:true});
serialDialog.querySelector('.serial-close').onclick=serialDialog.querySelector('.serial-cancel').onclick=()=>serialDialog.close();serialDialog.querySelector('.serial-confirm').onclick=()=>{if(!activeSerialRow)return;const values=[...serialFields.querySelectorAll('input')].map(input=>input.value.trim()),filled=values.filter(Boolean);if(new Set(filled).size!==filled.length){alert('Aynı seri numarası birden fazla girilemez.');return}activeSerialRow.querySelector('.serials').value=JSON.stringify(values);syncSerialButton(activeSerialRow);serialDialog.close()};serialDialog.addEventListener('close',()=>activeSerialRow=null);
document.getElementById('add').onclick=()=>add();date.oninput=()=>{const d=date.value.replace(/\D/g,'').slice(0,8);date.value=d.length>4?d.slice(0,2)+'.'+d.slice(2,4)+'.'+d.slice(4):d.length>2?d.slice(0,2)+'.'+d.slice(2):d};document.querySelector('form').onsubmit=e=>{if(!/^\d{2}\.\d{2}\.\d{4}$/.test(date.value)){e.preventDefault();alert('Tarih gg.aa.yyyy formatında olmalıdır.')}else{const r=[...body.rows].find(x=>!x.querySelector('.sid').value);if(r){e.preventDefault();alert('Her kalemde listeden stok kartı seçin.');r.querySelector('.search').focus()}}};(initial.length?initial:[{}]).forEach(add)})();
</script>
<style>.inv2{max-width:1550px;margin:30px auto;padding:0 18px}.inv2>section{padding:24px;border:1px solid #e1e2e8;border-radius:10px;background:#fff}.inv2 h1{margin:0 0 5px}.inv2 header p{margin:0;color:#7b7b8d}.err{padding:12px;background:#ffe3e3;color:#a21d1d}.head{display:grid;grid-template-columns:2fr 1fr 1fr;gap:16px;margin:22px 0}.head label{display:flex;flex-direction:column;gap:6px}.inv2 input,.inv2 select{box-sizing:border-box;width:100%;height:40px;padding:0 10px;border:1px solid #d5d3de;border-radius:6px;background:#fff;font:inherit}.inv2 table{width:100%;border-collapse:collapse}.inv2 th,.inv2 td{padding:8px;border-bottom:1px solid #e1e2e8;text-align:left}.inv2 th{font-size:12px}.inv2 th:nth-child(3),.inv2 td:nth-child(3){width:82px}.inv2 th:last-child,.inv2 td:last-child{width:36px;padding-right:0;padding-left:0;text-align:center}.qty{width:82px!important}.unit{min-width:105px}.vat{min-width:76px}.discount{min-width:95px}.purchase-total{min-width:110px}.picker{position:relative}.results{position:absolute;z-index:20;top:48px;right:8px;left:8px;max-height:230px;overflow:auto;border:1px solid #d5d3de;background:#fff}.results button{display:block;width:100%;padding:9px;border:0;background:#fff;color:#2f2b3d;text-align:left}.vat-total,.list{white-space:nowrap}.remove,footer>*{display:inline-grid;place-items:center;border:0;border-radius:7px;color:#fff;text-decoration:none}.remove{box-sizing:border-box!important;width:36px!important;min-width:36px!important;max-width:36px!important;height:36px!important;min-height:36px!important;max-height:36px!important;padding:0!important;background:#e04f55;font-size:20px}.inv2 footer{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}.inv2 footer>*{box-sizing:border-box!important;width:36px!important;min-width:36px!important;max-width:36px!important;height:36px!important;min-height:36px!important;max-height:36px!important;padding:0!important}.add{margin-right:auto;background:#f5a33b;font-size:22px}.cancel{background:#e04f55;font-size:21px}.save{background:#19a94b}.save svg{width:18px;fill:none;stroke:#fff;stroke-width:2}@media(max-width:900px){.head{grid-template-columns:1fr}.wrap{overflow:auto}.inv2 table{min-width:1300px}}</style>
